import itertools,json
people=set('KLMNPQR'); west=set('KQR')
optsA=['KNR','MNP','LMQ','LNR','MNR']
optsB=['KLN','NPR','PQR','KMP','LPQ']
daysA=[{2,6},{1,4,7},{6,7},{3,5},{1,6}]
daysB=[{4,7},{2},{3,7},{4,5},{3,5,8}]
As=[a for a in itertools.product(*optsA) if len(set(a))==5]
Bs=[b for b in itertools.product(*optsB) if len(set(b))==5]
def score(a,b):
    days={p:set() for p in people}
    for ids,ds in [(a,daysA),(b,daysB)]:
        for p,d in zip(ids,ds): days[p].update(d)
    return sum(len(d)>=3 for d in days.values())
feasible=[]
for a,b in itertools.product(As,Bs):
    common=set(a)&set(b)
    if len(common)==3 and len(common&west)==1:
        feasible.append((score(a,b),a,b))
lo=min(feasible); hi=max(feasible)
result={'feasible_linkages':len(feasible),'bounds':[lo[0],hi[0]],'low_witness':{'A':''.join(lo[1]),'B':''.join(lo[2])},'high_witness':{'A':''.join(hi[1]),'B':''.join(hi[2])},'decision':'confirmed' if lo[0]>=3 else 'excluded' if hi[0]<3 else 'undetermined'}
payload=json.dumps(result)
r=json.loads(payload)
assert set(r)=={'feasible_linkages','bounds','low_witness','high_witness','decision'}
for name,target in [('low_witness',r['bounds'][0]),('high_witness',r['bounds'][1])]:
    w=r[name]; assert set(w)=={'A','B'}
    a,b=w['A'],w['B']
    assert len(a)==len(b)==5 and len(set(a))==len(set(b))==5
    assert all(p in o for p,o in zip(a,optsA)) and all(p in o for p,o in zip(b,optsB))
    assert len(set(a)&set(b))==3 and len(set(a)&set(b)&west)==1
    assert score(a,b)==target
# Independent traversal over labeled roster permutations and date-centric scoring.
count=0; scores=[]
for a in itertools.permutations(sorted(people),5):
    if not all(p in o for p,o in zip(a,optsA)): continue
    for b in itertools.permutations(sorted(people),5):
        if not all(p in o for p,o in zip(b,optsB)): continue
        shared=[p for p in people if p in a and p in b]
        if len(shared)!=3 or sum(p in west for p in shared)!=1: continue
        count+=1
        credits={p:0 for p in people}
        for date in range(1,9):
            present={p for p,d in zip(a,daysA) if date in d}|{p for p,d in zip(b,daysB) if date in d}
            for p in present: credits[p]+=1
        scores.append(sum(n>=3 for n in credits.values()))
assert count==r['feasible_linkages'] and [min(scores),max(scores)]==r['bounds']
assert r['decision']==('confirmed' if all(s>=3 for s in scores) else 'excluded' if all(s<3 for s in scores) else 'undetermined')
print(payload)
print('Verified independently:',count,'assignments; score distribution:',{s:scores.count(s) for s in sorted(set(scores))})

